  "search_result": null
}

{
  "analysis": "The review describes spending money as a route to receiving better teammates, while non-paying players are assigned worse teammates and bots. This supports M_PayToProgress because payment grants an in-game competitive advantage, and S_Competition because the mechanic concerns ranked/team matches and winning or losing against other players. P_IllusionOfControl was considered but rejected: although the reviewer alleges biased teammate selection, the span does not clearly describe the game deceiving players about their skill or hiding outcome information. S_EncouragesAntiSocialBehavior was rejected because blaming teammates is player behavior, not a game incentive for harmful conduct.",
  "labels": [
    {
      "label": "M_PayToProgress",
      "span": "only if you invest some money in the game will the teammates will be good otherwise the game will select the worst ones for you",
      "rationale": "Spending money is described as granting better teammates, an in-game advantage in competition."
    },
    {
      "label": "S_Competition",
      "span": "everyone will just play solo and then blame you for the loss",
      "rationale": "The span describes team-based competitive play with wins and losses."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

{
  "analysis": "The review describes repeated near-miss outcomes and explicitly claims that games are rigged to induce spending. This supports P_IllusionOfControl because the reviewer alleges manipulated game outcomes. The repeated failures just short of winning support P_OptimismAndFrequencyBiases because they describe a clustering of near-successes. The constant purchase prompts do not establish M_EasyToPurchase under its boundary rule because no interception of play, insufficient-funds trigger, default purchase, or obstructed opt-out is described. M_PayToProgress is rejected because payment is not explicitly described as required to advance, and no Advertisement or Reward Mania mechanic is described.",
  "labels": [
    {
      "label": "P_IllusionOfControl",
      "span": "almost every game is rigged to make you spend",
      "rationale": "The reviewer explicitly alleges that the game manipulates outcomes to induce spending."
    },
    {
      "label": "P_OptimismAndFrequencyBiases",
      "span": "a level is failed 1 or 2 moves from winning. 20 or 30 times in a row",
      "rationale": "This describes repeated clustered near-wins, an instance of perceived frequent near-successes."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

{
  "analysis": "The review describes spending money as necessary to level up, which satisfies Pay to Progress. I considered Intermediate Currency, but the review does not clearly describe real money being converted into in-game currency. I rejected Competition because multiplayer or high-level advantages are not explicitly described as player-versus-player competition, and rejected Grinding because no repetitive progress activity is named.",
  "labels": [
    {
      "label": "M_PayToProgress",
      "span": "Hope your rich, cause that the only way your gonna level up in the beginning.",
      "rationale": "The span describes real-world wealth or spending as the only route to leveling up."
    }
  ],
  "invoked_web_search": false,
