  "labels": [
    {
      "label": "M_PayToProgress",
      "span": "It does take money to pass some of the levels",
      "rationale": "The span states that spending money enables progress past levels."
    },
    {
      "label": "S_Reciprocity",
      "span": "You can request lives from teammates",
      "rationale": "The span describes requesting resources from other players."
    },
    {
      "label": "T_PlayingByAppointment",
      "span": "instead of having to wait for them to refill",
      "rationale": "The span describes an in-game life-regeneration wait that limits when the player can continue."
    }
  ],
  "invoked_web_search": false,
